const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const ROOT = CFG.data_dir;
const fs = require('fs');
const RL = ROOT + '/state/reels_ledger.json';
const readRL = () => { try { return JSON.parse(fs.readFileSync(RL, 'utf8')); } catch (e) { return {version: 1, entries: []}; } };
const saveRL = l => { const t = RL + '.tmp'; fs.writeFileSync(t, JSON.stringify(l, null, 2)); fs.renameSync(t, RL); };
const geminiText = j => { try { return (j.candidates[0].content.parts || []).filter(p => !p.thought).map(p => p.text || '').join(''); } catch (e) { return ''; } };
const parseJson = t => { try { return JSON.parse(String(t || '').replace(/```(?:json)?/gi, '').trim()); } catch (e) { return null; } };
const JEV_MODEL = CFG.jev_model || 'typesafe/jev-1.13';
const JEV_ON = CFG.jev_enabled !== false;
const shortName = d => String(d || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
const productLine = d => { const s = shortName(d); const p = String(CFG.product_prefix || '').trim(); return p && !s.toLocaleLowerCase(LOC).startsWith(p.toLocaleLowerCase(LOC)) ? p + ' ' + s : s; };

// Frames published recently WITH an approved AI reframe: 4 different dishes, 9:16 story frames first
const ledgerPath = ROOT + '/state/ledger.json';
if (!fs.existsSync(ledgerPath)) throw new Error('No ledger yet (' + ledgerPath + '): the reel is built from frames the autopublisher has published');
const L = JSON.parse(fs.readFileSync(ledgerPath, 'utf8')).entries || [];
const rl = readRL();
const recentFrames = new Set(rl.entries.slice(-2).flatMap(e => e.frames || []));
const framePath = e => { for (const ext of ['jpg', 'png']) { const p = ROOT + '/work/' + e.base + '_' + e.kind + '.' + ext; if (fs.existsSync(p)) return p; } return ''; };
const now = Date.now();
const pool = L.filter(e => e.status === 'published' && e.framed === true && e.dish).map(e => ({base: e.base, kind: e.kind, dish: e.dish, caption: e.caption || '', title: e.redTitle || '',
  publishedAt: e.publishedAt, age: (now - Date.parse(e.publishedAt || e.createdAt || 0)) / 864e5, path: framePath(e)})).filter(e => e.path);
const pick = []; const dishes = new Set();
// First frames not used in the last two reels; if the pool is small, allow them too.
// Windows: last 8 days, then 30 days, then everything.
for (const allowRecent of [false, true]) {
  for (const win of [8, 30, 3650]) {
    const c = pool.filter(e => e.age <= win && (allowRecent || !recentFrames.has(e.base))).sort((a, b) => (a.kind === b.kind ? a.age - b.age : (a.kind === 'story' ? -1 : 1)));
    for (const e of c) { if (pick.length >= 4) break; if (!dishes.has(e.dish)) { dishes.add(e.dish); pick.push(e); } }
    if (pick.length >= 4) break;
  }
  if (pick.length >= 3) break;
}
if (pick.length < 2) throw new Error('Not enough frames for a reel (' + pick.length + '); it needs published, AI-reframed images of at least 2 different dishes');
const d = new Date(); const id = 'reel_' + d.toISOString().slice(0, 10).replace(/-/g, '') + '_' + Math.random().toString(36).slice(2, 7);
rl.entries.push({id, status: 'reserved', frames: pick.map(p => p.base), dishes: pick.map(p => p.dish), createdAt: d.toISOString()}); saveRL(rl);
// Jev: which frame turns into the most appetizing slow cinematic video (steam, sizzle)?
const criteria = {}; pick.forEach((p, i) => criteria['k' + i] = p.dish + ' — ' + (p.caption || p.title).slice(0, 160));
return [{json: {id, frames: pick, body: {model: JEV_MODEL, state: {restaurant: CFG.brand_name + ' - ' + (CFG.brand_context || 'a restaurant'), candidates: pick.map((p, i) => ({option: 'k' + i, dish: p.dish, description: p.caption || p.title}))},
  questions: {hero: {type: 'choice', instructions: 'Which of these dishes will look most appetizing as the opening shot of an Instagram Reel, animated as a slow cinematic camera push-in with rising steam and glistening, sizzling food? Dishes with visible texture, char or glaze (for example grilled meat on skewers or plates) usually work better than wrapped or flat food.', criteria}}}}}];

