const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const ROOT = CFG.data_dir;
const fs = require('fs');
const RL = ROOT + '/state/reels_ledger.json';
const readRL = () => { try { return JSON.parse(fs.readFileSync(RL, 'utf8')); } catch (e) { return {version: 1, entries: []}; } };
const saveRL = l => { const t = RL + '.tmp'; fs.writeFileSync(t, JSON.stringify(l, null, 2)); fs.renameSync(t, RL); };
const geminiText = j => { try { return (j.candidates[0].content.parts || []).filter(p => !p.thought).map(p => p.text || '').join(''); } catch (e) { return ''; } };
const parseJson = t => { try { return JSON.parse(String(t || '').replace(/```(?:json)?/gi, '').trim()); } catch (e) { return null; } };
const JEV_MODEL = CFG.jev_model || 'typesafe/jev-1.13';
const JEV_ON = CFG.jev_enabled !== false;
const shortName = d => String(d || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
const productLine = d => { const s = shortName(d); const p = String(CFG.product_prefix || '').trim(); return p && !s.toLocaleLowerCase(LOC).startsWith(p.toLocaleLowerCase(LOC)) ? p + ' ' + s : s; };

const k = $('Build Script Prompt').first().json;
const ai = parseJson(geminiText($json)) || {};
const norm = s => String(s || '').trim().toLocaleLowerCase(LOC);
const clean = s => String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
const reEsc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const bannedList = (CFG.banned_phrases || []).filter(Boolean);
const cliche = bannedList.length ? new RegExp('(?<![\\p{L}\\p{N}])(?:' + bannedList.map(reEsc).join('|') + ')(?![\\p{L}\\p{N}])', 'iu') : null;
const prohibited = CFG.prohibited_pattern ? new RegExp(CFG.prohibited_pattern, 'iu') : null;
const n = k.frames.length;
const LW = CFG.reel_line_max_words || 4, LC = CFG.reel_line_max_chars || 30;
// The short call to action rotates through an approved list (generated ones drifted into broken grammar)
const CTAS = (CFG.reel_ctas && CFG.reel_ctas.length) ? CFG.reel_ctas : ['Tell us in the comments'];
const CTA2 = CTAS[readRL().entries.length % CTAS.length];
const why = o => {
  if (!Array.isArray(o.lines) || o.lines.length !== n) return 'wrong number of slogans';
  for (let i = 0; i < n; i++) { const t = o.lines[i];
    if (!t) return 'empty slogan'; if (t.length > LC || t.split(/\s+/).length > LW) return 'slogan too long: ' + t;
    if (norm(t).includes(norm(shortName(k.frames[i].dish)))) return 'slogan repeats the dish name'; }
  if (!o.cta1 || !/[?？؟]$/.test(o.cta1) || o.cta1.split(/\s+/).length > 7 || o.cta1.length > 40) return 'closing question not suitable';
  if (!o.caption || o.caption.length < 40 || o.caption.length > 300) return 'caption length';
  const all = [...o.lines, o.cta1, o.cta2, o.caption].join(' ');
  if ((prohibited && prohibited.test(all)) || all.includes('#')) return 'prohibited phrase';
  if (cliche && cliche.test(all)) return 'banned cliché';
  return '';
};
const cands = [], fails = [];
(Array.isArray(ai.options) ? ai.options : []).forEach((o, i) => {
  const c = {id: 's' + (i + 1), lines: (o.lines || []).map(x => clean(x).replace(/[.!…]+$/, '')), cta1: clean(o.cta1), cta2: CTA2, caption: clean(o.caption)};
  const w = why(c); if (w) fails.push({...c, fail: w}); else cands.push(c);
});
// "Weakest line" grammar question: averaging over all lines missed a single broken line
const Q = {
  grammar: {type: 'score', instructions: 'Look at every on-screen line separately (each slogan, the closing question and the closing call). Rate the ' + LANG + ' grammar and naturalness of the WORST single line. A short headline may be a noun phrase, but it must be complete and idiomatic; wrong inflections or verb forms make it broken.', criteria: ['broken or incomplete ' + LANG, 'awkward or unnatural', 'correct but plain', 'natural, fluent ' + LANG]},
  appeal: {type: 'score', instructions: 'How appetizing, specific and varied are the on-screen slogans for a Reel of ' + (CFG.brand_context || 'a restaurant') + '?', criteria: ['generic or dull', 'acceptable', 'appetizing', 'very appetizing and specific']},
  fit: {type: 'noul', instructions: 'Does every slogan fit the dish it is paired with (it describes something plausible for that dish, e.g. not skewers for a wrap)?', criteria: {true: 'All slogans fit their dishes', false: 'At least one slogan contradicts its dish'}},
  cta: {type: 'score', instructions: 'How engaging is the closing question plus call to action at inviting comments?', criteria: ['weak', 'acceptable', 'good', 'very engaging']},
  caption: {type: 'score', instructions: 'Rate the Instagram caption: natural ' + LANG + ', appetizing, mentions the dishes, not a hard sell.', criteria: ['poor', 'acceptable', 'good', 'excellent']}
};
const items = cands.map((c, i) => ({json: {idx: i, cand: c, body: {model: JEV_MODEL, state: {brand: CFG.brand_name + ' - ' + (CFG.brand_context || 'a restaurant'), format: 'Instagram Reel',
  shots: k.frames.map((f, j) => ({dish: f.dish, slogan: c.lines[j]})), closing_question: c.cta1, closing_call: c.cta2, caption: c.caption}, questions: Q}}}));
if (!items.length) items.push({json: {idx: -1, cand: null, body: {model: JEV_MODEL, state: 'connectivity check', questions: {ok: {type: 'noul', instructions: 'Is this a connectivity check?', criteria: {true: 'yes', false: 'no'}}}}}});
items[0].json.fails = fails;
return items;

const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const ROOT = CFG.data_dir;
const fs = require('fs');
const RL = ROOT + '/state/reels_ledger.json';
