const JEV_MODEL = CFG.jev_model || 'typesafe/jev-1.13';
const JEV_ON = CFG.jev_enabled !== false;
const shortName = d => String(d || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
const productLine = d => { const s = shortName(d); const p = String(CFG.product_prefix || '').trim(); return p && !s.toLocaleLowerCase(LOC).startsWith(p.toLocaleLowerCase(LOC)) ? p + ' ' + s : s; };

const k = $('Build Script Prompt').first().json;
const reqs = $('Script Questions').all(); const res = $input.all();
const rated = [];
reqs.forEach((r, i) => { if (r.json.idx < 0) return; const a = res[i] && res[i].json && res[i].json.answers;
  // Jev unreachable/disabled (or an incomplete answer): keep the candidate, it already passed the rules
  if (!a || !a.grammar || !a.appeal || !a.fit || !a.cta || !a.caption) { rated.push({...r.json.cand, q: null, ok: true}); return; }
  const g = a.grammar.score, ap = a.appeal.score, fit = a.fit.noul, cta = a.cta.score, cap = a.caption.score;
  const q = 0.30 * ap / 3 + 0.25 * g / 3 + 0.15 * fit + 0.15 * cta / 3 + 0.15 * cap / 3;
  rated.push({...r.json.cand, q: Math.round(q * 1000) / 1000, ok: g >= 1.5 && fit >= 0.4, scores: {grammar: g, appeal: ap, fit, cta, caption: cap}});
});
const sc = c => c.q == null ? 0.5 : c.q;
let best = rated.filter(c => c.ok).sort((a, b) => sc(b) - sc(a))[0];
let source = JEV_ON ? 'jev' : 'rules only';
if (!best) { // safe fallback script: product lines only + a fixed closing card
  source = 'fallback';
  const F = CFG.reel_fallback || {};
  const names = k.frames.map(f => shortName(f.dish).toLocaleLowerCase(LOC));
  let list; try { list = new Intl.ListFormat(LOC, {style: 'long', type: 'conjunction'}).format(names); } catch (e) { list = names.join(', '); }
  best = {id: 'fallback', lines: k.frames.map((_, i) => i === 0 ? (F.first_line || '') : ''), cta1: F.question || 'Which one is your favourite?',
    cta2: F.cta || (CFG.reel_ctas || [])[0] || '', caption: String(F.caption || '{dishes}').replace('{brand}', CFG.brand_name).replace('{dishes}', list), q: null};
}
return [{json: {...k, body: undefined, script: best, scriptSource: source, scriptRated: rated, scriptFails: reqs[0].json.fails || []}}];

